var DATA = {"method": "Shading analysis", "samples": "0,0,1:0.9|0.7,0,0.7:0.7|0,0.7,0.7:0.7|-0.7,0,0.7:0.3|0,-0.7,0.7:0.3|0,0,-1:0.2"};
console.log("Method: " + DATA.method);
// samples like "nx,ny,nz:brightness" from a diffuse sphere; estimate light dir via weighted average
var pts = DATA.samples.split("|").map(function (s) {
  var p = s.split(":"); var n = p[0].split(",").map(function (v) { return parseFloat(v); });
  return { n: n, b: parseFloat(p[1]) };
});
var L = [0, 0, 0], wsum = 0;
pts.forEach(function (p) {
  var w = Math.max(0, p.b - 0.2); // above ambient
  L[0] += p.n[0] * w; L[1] += p.n[1] * w; L[2] += p.n[2] * w; wsum += w;
});
var len = Math.sqrt(L[0] * L[0] + L[1] * L[1] + L[2] * L[2]) || 1;
L = [L[0] / len, L[1] / len, L[2] / len];
console.log("Estimated light direction: (" + L.map(function (v) { return v.toFixed(3); }).join(", ") + ")");
console.log("Samples used: " + pts.length);
console.log("RESULT: light direction recovered from diffuse shading.");

